use serde::{Deserialize, Serialize};

use super::identifiers::ObjectId;
use super::phase::Phase;
use super::player::PlayerId;
use super::zones::Zone;

/// A structured game log entry with typed segments and metadata.
/// Generated by the engine post-hoc from `GameEvent`s with resolved card/player names.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GameLogEntry {
    pub seq: u32,
    /// The game of the match this entry was logged in
    /// (`match_flow::game_on_board`), numbered as `GameState::game_number`.
    ///
    /// The next game of a best-of-three replaces the game in place while a
    /// client's log runs on across it, and turn numbers restart with every
    /// game, so this, not the turn or the text, tells one game's entries from
    /// another's. The first game's entries leave it off the wire, so a single
    /// game and a match's first game serialize as they did before the field;
    /// an entry without it (one of those, a save that predates the field, or
    /// one the client writes itself) reads as the first game's.
    #[serde(
        default = "super::game_state::default_game_number",
        skip_serializing_if = "super::game_state::is_first_game"
    )]
    pub game_number: u8,
    pub turn: u32,
    pub phase: Phase,
    pub category: LogCategory,
    pub segments: Vec<LogSegment>,
    #[serde(default)]
    pub presentation: LogPresentation,
}

/// Engine-authored display metadata for a log entry. Consumers may choose a
/// denser presentation, but must not infer importance or tone from text.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct LogPresentation {
    #[serde(default)]
    pub importance: LogImportance,
    #[serde(default)]
    pub tone: LogTone,
    #[serde(default)]
    pub boundary: LogBoundary,
    #[serde(default)]
    pub visibility: LogVisibility,
}

impl Default for LogPresentation {
    fn default() -> Self {
        Self {
            importance: LogImportance::Detail,
            tone: LogTone::Neutral,
            boundary: LogBoundary::None,
            visibility: LogVisibility::Public,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum LogImportance {
    Essential,
    Context,
    #[default]
    Detail,
    Diagnostic,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum LogTone {
    #[default]
    Neutral,
    Positive,
    Negative,
    Informational,
    Diagnostic,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum LogBoundary {
    #[default]
    None,
    Turn,
    Phase,
}

/// Whether an entry is safe in the normal game log. The client must require an
/// explicit diagnostic opt-in before showing hidden information.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum LogVisibility {
    #[default]
    Public,
    HiddenInformation,
}

/// A typed segment of a log entry, enabling rich UI rendering.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", content = "value")]
pub enum LogSegment {
    Text(String),
    CardName { name: String, object_id: ObjectId },
    PlayerName { name: String, player_id: PlayerId },
    Number(i32),
    Mana(String),
    Zone(Zone),
    Keyword(String),
}

/// Categories for log entries, used for verbosity filtering in the frontend.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum LogCategory {
    Game,
    Turn,
    Stack,
    Combat,
    Zone,
    Life,
    Mana,
    State,
    Token,
    Trigger,
    Special,
    Destroy,
    Debug,
}
